from __future__ import annotations

import os
import shutil
from pathlib import Path


def get_engine_root() -> Path:
    """
    Install / source checkout root for Transub Engine.
    Override with TRANSUB_ENGINE_HOME (or TRANSUB_ENGINE_ROOT).
    """
    from .paths import get_engine_home

    return get_engine_home()


def bundled_ffmpeg_candidates(root: Path | None = None) -> list[Path]:
    base = root or get_engine_root()
    names = ("ffmpeg.exe", "ffmpeg") if os.name == "nt" else ("ffmpeg", "ffmpeg.exe")
    # Engine checkout is often ``…/Transub/transub-engine`` while the desktop
    # app ships ffmpeg at ``…/Transub/_internal/bin`` (or next to the .exe).
    search_roots = [base]
    parent = base.parent
    if parent != base:
        search_roots.append(parent)
    out: list[Path] = []
    for search in search_roots:
        for name in names:
            out.append(search / "_internal" / "bin" / name)
            out.append(search / "_internal" / name)
            out.append(search / "bin" / name)
    return out


def resolve_ffmpeg() -> str:
    """
    Resolve ffmpeg executable path.
    Priority: FFMPEG_BINARY / FFMPEG_PATH → engine `_internal/bin` → PATH.
    """
    for key in ("FFMPEG_BINARY", "FFMPEG_PATH"):
        candidate = str(os.environ.get(key) or "").strip().strip('"')
        if not candidate:
            continue
        path = Path(candidate)
        if path.is_file():
            return str(path.resolve())
        # Allow pointing at a directory that contains ffmpeg
        if path.is_dir():
            for name in (("ffmpeg.exe", "ffmpeg") if os.name == "nt" else ("ffmpeg", "ffmpeg.exe")):
                nested = path / name
                if nested.is_file():
                    return str(nested.resolve())

    for candidate in bundled_ffmpeg_candidates():
        if candidate.is_file():
            return str(candidate.resolve())

    which = shutil.which("ffmpeg")
    return which or ""


def resolve_ffprobe() -> str:
    for key in ("FFPROBE_BINARY", "FFPROBE_PATH"):
        candidate = str(os.environ.get(key) or "").strip().strip('"')
        if candidate and Path(candidate).is_file():
            return str(Path(candidate).resolve())

    ffmpeg = resolve_ffmpeg()
    if ffmpeg:
        sibling = Path(ffmpeg).with_name("ffprobe.exe" if os.name == "nt" else "ffprobe")
        if sibling.is_file():
            return str(sibling.resolve())
        # Windows: ffmpeg.exe → ffprobe.exe
        if Path(ffmpeg).name.lower() == "ffmpeg.exe":
            alt = Path(ffmpeg).parent / "ffprobe.exe"
            if alt.is_file():
                return str(alt.resolve())

    root = get_engine_root()
    for name in (("ffprobe.exe", "ffprobe") if os.name == "nt" else ("ffprobe", "ffprobe.exe")):
        for candidate in (root / "_internal" / "bin" / name, root / "_internal" / name):
            if candidate.is_file():
                return str(candidate.resolve())

    which = shutil.which("ffprobe")
    return which or ""


def ensure_ffmpeg_on_path() -> str:
    """
    Ensure resolved ffmpeg's directory is on PATH and env vars are set.
    FunASR / torchaudio look for a bare `ffmpeg` on PATH.
    Returns the resolved executable path (may be empty).
    """
    ff = resolve_ffmpeg()
    if not ff:
        return ""
    directory = str(Path(ff).parent)
    path_env = os.environ.get("PATH", "")
    parts = path_env.split(os.pathsep) if path_env else []
    if directory and directory not in parts:
        os.environ["PATH"] = directory + os.pathsep + path_env
    os.environ["FFMPEG_BINARY"] = ff
    os.environ["FFMPEG_PATH"] = ff
    probe = resolve_ffprobe()
    if probe:
        os.environ.setdefault("FFPROBE_BINARY", probe)
        os.environ.setdefault("FFPROBE_PATH", probe)
    return ff
